import , re

def run_skill(skill_fn, prompt, max_retry=2):
    # 1️⃣ 输入校验:空值直接拦,不浪费token
    if not prompt or not isinstance(prompt, str):
        return {'ok': False, 'error': 'invalid_input'}

    resp = skill_fn(prompt)
    for i in range(max_retry + 1):
        # 2️⃣ 输出清洗:剥掉包裹,抠出JSON主体
        raw = re.sub(r'()?|', '', resp).strip()
        m = re.search(r'\{.*\}|\[.*\]', raw, re.S)
        try:
            data = .loads(m.group() if m else raw)
            return {'ok': True, 'data': data, 'retry': i}  # ✅ 成功
        except Exception as e:
            # 3️⃣ 失败重试:报错回喂,带hint精准纠错
            resp = skill_fn(prompt + '\n\n你上次输出报错:' + str(e) +
                            '\n只输出JSON,不要解释,不要代码块')
    return {'ok': False, 'error': 'retry_exhausted'}  # 到顶放弃,防死循环

# ===== 最小可用Skill:文本速算器(约20行) =====
# 1️⃣ skill身份卡:告诉agent我是谁、管什么
SKILL = {
    'name': 'text_stats',               # 唯一名字
    'description': '统计文本字数与词数',  # 给agent看的说明书
    'trigger': ['统计', '字数'],         # 触发词,命中才干活
}

# 2️⃣ 核心逻辑:真正干活,只管输入→输出
def run(text: str) -> str:
    chars = len(text)                   # 总字符数
    words = len(text.split())           # 按空格分词
    pure = len(text.replace(' ', ''))   # 去空格后的字数
    return f'字数:{chars}|词数:{words}|去空格:{pure}'

# 3️⃣ 调度器:agent的前台,决定接不接这单
def dispatch(query: str):
    if not any(k in query for k in SKILL['trigger']):
        return None                     # 不归我管,放行给下一个skill
    text = query.split(':', 1)[-1]      # 取冒号后面的正文
    return run(text)

# 4️⃣ 首次调用:存成skill.py,直接 python skill.py
if __name__ == '__main__':
    print(dispatch('统计:今天也要开心呀 Keep going'))

# main_skill.py —— 主skill:采集→成稿→配图 链式编排
import 
from runtime import run_skill  # 平台提供的skill调用入口

def pipeline(keyword: str, num: int = 5) -> dict:
    # 1️⃣ 调子skill:素材采集
    collect = run_skill("collector", {
        "keyword": keyword,
        "limit": num
    })
    materials = collect["output"]["items"]

    # 2️⃣ 调子skill:成稿,采集结果直接作参数传入
    draft = run_skill("writer", {
        "topic": keyword,
        "materials": materials,
        "style": "小红书口吻",
        "word_count": 600
    })

    # 3️⃣ 调子skill:配图,复用成稿标题保证图文一致
    cover = run_skill("designer", {
        "title": draft["output"]["title"],
        "palette": "奶油风"
    })

    return {
        "draft": draft["output"],
        "cover_url": cover["output"]["url"]
    }

if __name__ == "__main__":
    print(.dumps(pipeline("通勤穿搭"), ensure_ascii=False, indent=2))
